<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{CalendarDays,ChevronRight,History}from'@lucide/vue';import{api,apiError,unpack}from'@/services/api';import type{ClinicalSession}from'@/types';import StatusPill from'@/components/StatusPill.vue';import ScoreRing from'@/components/ScoreRing.vue';import{useLocaleStore}from'@/stores/locale'
const sessions=ref<ClinicalSession[]>([]),loading=ref(true),error=ref(''),status=ref('all'),locale=useLocaleStore();const filtered=computed(()=>sessions.value.filter(s=>status.value==='all'||s.status===status.value))
onMounted(async()=>{try{sessions.value=unpack(await api.getSessions())}catch(e){error.value=apiError(e)}finally{loading.value=false}})
</script>
<template><div class="page"><header class="page-header"><div><div class="page-eyebrow">{{ locale.t('Your learning record') }}</div><h1>{{ locale.t('Practice history') }}</h1><p class="subtitle">{{ locale.t('Review previous consultations and return to evidence-linked feedback.') }}</p></div></header><div class="filter-row"><select v-model="status" class="select"><option value="all">{{ locale.t('All attempts') }}</option><option value="completed">{{ locale.t('Completed') }}</option><option value="active">{{ locale.t('In progress') }}</option></select></div><div v-if="error" class="alert alert--error">{{error}}</div><div v-if="loading" class="loading"><div class="spinner"></div></div><section v-else class="history-list"><RouterLink v-for="item in filtered" :key="item.id" class="card history-row" :to="item.status==='completed'&&item.resultId?`/student/feedback/${item.resultId}`:`/student/consultation/${item.id}`"><div class="history-icon"><History :size="19"/></div><div><h3>{{item.caseTitle}}</h3><span><CalendarDays :size="13"/>{{new Date(item.startedAt).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'})}} · {{Math.round((item.durationSeconds||0)/60)}} {{ locale.t('min') }}</span></div><StatusPill :value="item.status"/><ScoreRing v-if="item.score!=null" :score="item.score" size="small"/><ChevronRight :size="18"/></RouterLink><div v-if="!filtered.length" class="card empty"><History/><h3>{{ locale.t('No practice attempts yet') }}</h3><p>{{ locale.t('Choose a case to start your first consultation.') }}</p><RouterLink class="button" to="/student/cases">{{ locale.t('Browse cases') }}</RouterLink></div></section></div></template>
<style scoped>.history-list{display:grid;gap:10px}.history-row{display:grid;grid-template-columns:auto 1fr auto auto auto;gap:17px;align-items:center;padding:15px 18px}.history-icon{width:42px;height:42px;display:grid;place-items:center;border-radius:11px;background:var(--green-soft);color:var(--green)}.history-row h3{margin:0}.history-row div:nth-child(2)>span{display:flex;align-items:center;gap:5px;color:var(--muted);font-size:10px}@media(max-width:650px){.history-row{grid-template-columns:auto 1fr auto}.history-row .score-ring{display:none}.history-row .status-pill{grid-column:2}.history-row>svg{grid-row:1/3;grid-column:3}}</style>
